import{_ as r,C as s,c as l,o as u,ag as o,j as e,G as n,a as i}from"./chunks/framework.Bw-5EFTY.js";const b=JSON.parse('{"title":"Paymattic Integration with FluentAffiliate","description":"","frontmatter":{},"headers":[],"relativePath":"guide/integrations/paymattic-integration-with-fluentaffiliate.md","filePath":"guide/integrations/paymattic-integration-with-fluentaffiliate.md","lastUpdated":1755603747000}'),c={name:"guide/integrations/paymattic-integration-with-fluentaffiliate.md"};function f(g,t,m,h,d,p){const a=s("ZoomableImage");return u(),l("div",null,[t[0]||(t[0]=o('<h1 id="paymattic-integration-with-fluentaffiliate" tabindex="-1">Paymattic Integration with FluentAffiliate <a class="header-anchor" href="#paymattic-integration-with-fluentaffiliate" aria-label="Permalink to &quot;Paymattic Integration with FluentAffiliate&quot;">​</a></h1><p>Paymattic is a fantastic payment and donation form builder for WordPress. By integrating it with FluentAffiliate, you can empower your affiliates to earn commissions on form submissions, turning your payment forms into powerful revenue streams.</p><p>This guide will walk you through a step-by-step process to connect Paymattic with FluentAffiliate.</p><div class="note custom-block github-alert"><p class="custom-block-title">NOTE</p><p>Before you begin, please make sure you have both the Paymattic and FluentAffiliate plugins installed and activated on your WordPress website.</p></div><h2 id="enable-paymattic-integration" tabindex="-1">Enable Paymattic Integration <a class="header-anchor" href="#enable-paymattic-integration" aria-label="Permalink to &quot;Enable Paymattic Integration&quot;">​</a></h2><p>First, you need to tell FluentAffiliate to connect with Paymattic.</p><ol><li>Go to your <strong>FluentAffiliate Dashboard</strong>.</li><li>Click on <strong>Settings</strong> in the top menu.</li><li>From the left sidebar, select the <strong>Integration Settings</strong> option.</li><li>You will see a list of available integrations. Find <strong>Paymattic</strong> in the list and click the toggle button to enable it.</li></ol><p>Your <strong>Paymattic</strong> integration with <strong>FluentAffiliate</strong> is now active, allowing affiliates to earn referral commissions on course sales.</p><p>In the <strong>Manage</strong> section, you&#39;ll find additional settings to customize how affiliate commissions work with your courses.</p>',9)),e("p",null,[n(a,{src:"/guide/public/images/integrations/paymattic/integration-setup-options.webp",alt:"Integration Settings"})]),t[1]||(t[1]=e("h2",{id:"configure-paymattic-settings",tabindex:"-1"},[i("Configure Paymattic Settings "),e("a",{class:"header-anchor",href:"#configure-paymattic-settings","aria-label":'Permalink to "Configure Paymattic Settings"'},"​")],-1)),t[2]||(t[2]=e("p",null,"Once you enable the integration, a settings pop-up will appear, giving you powerful options to control how commissions are handled for your forms.",-1)),t[3]||(t[3]=e("p",null,"Here’s a breakdown of the settings you'll see:",-1)),t[4]||(t[4]=e("ul",null,[e("li",null,[e("strong",null,"Enable Affiliate Integration for Paymattic:"),i(" This is the main switch for the integration. It must be checked for the integration to work.")]),e("li",null,[e("strong",null,"Enable custom rate for specific forms:"),i(" Check this box if you want to set different commission rates for different Paymattic forms. This is perfect if you want to offer a higher commission on a specific product or service form. This setting will override the default commission rate you have set globally.")])],-1)),e("p",null,[n(a,{src:"/guide/public/images/integrations/paymattic/paymattic-settings-configuration.webp",alt:"Paymattic Settings"})]),t[5]||(t[5]=o('<h3 id="setting-a-custom-rate" tabindex="-1">Setting a Custom Rate <a class="header-anchor" href="#setting-a-custom-rate" aria-label="Permalink to &quot;Setting a Custom Rate&quot;">​</a></h3><p>If you enabled custom rates, you can configure them easily:</p><ol><li><strong>Paymattic Forms:</strong> Click on the &quot;Select&quot; field to choose a specific Paymattic form from a dropdown list.</li><li><strong>Select Rate:</strong> Enter the commission amount you want to offer for that form. You can choose between a <strong>Percentage (%)</strong> or a <strong>Fixed</strong> amount from the dropdown on the right.</li><li><strong>Add New Group:</strong> If you need to set a custom rate for another form, simply click the <strong>+ Add New Group</strong> button. This will add a new row where you can select another form and set its unique commission rate.</li><li><strong>Save Settings:</strong> Once you are done with your configuration, don’t forget to click the <strong>Save Settings</strong> button to make sure all your changes are applied.</li></ol><h2 id="generate-an-affiliate-link" tabindex="-1">Generate an Affiliate Link <a class="header-anchor" href="#generate-an-affiliate-link" aria-label="Permalink to &quot;Generate an Affiliate Link&quot;">​</a></h2><p>After you&#39;ve set everything up, your affiliates can start promoting your forms. To learn more about how can generate your <a href="/guide/affiliate-portal/generating-affiliate-links">affiliate link</a>, read this article.</p><p>Your affiliate can now <strong>copy</strong> this link and share it on their blog, social media, or with their audience. When a user clicks this link and submits the form, the affiliate will earn a commission!</p><h2 id="troubleshooting-common-issues" tabindex="-1">Troubleshooting Common Issues <a class="header-anchor" href="#troubleshooting-common-issues" aria-label="Permalink to &quot;Troubleshooting Common Issues&quot;">​</a></h2><p>Here are solutions to common issues you might encounter:</p><ul><li><strong>Commissions Not Tracking:</strong> Double-check that the integration toggle is enabled in the settings. You can also test an affiliate link in an incognito browser window to ensure it&#39;s working correctly.</li></ul><p>And that&#39;s it! You have successfully connected Paymattic with FluentAffiliate, creating another great way to boost your sales.</p>',10))])}const w=r(c,[["render",f]]);export{b as __pageData,w as default};
